"""Unidades extras da trilha de built-ins: combinações, pegadinhas e desafios.

Importado por gerar_builtins.py. Aqui as lições não são de uma função só: misturam
várias built-ins. Os exercícios de código têm uma solução de referência que o
gerador roda contra os testes (e confere que o código inicial NÃO passa).
"""

def OUT(code, errados, e):
    return {"k": "out", "c": code, "_wrong": errados, "e": e, "_in": ""}
def TYPE(code, e):
    return {"k": "type", "c": code, "e": e, "_in": ""}
def MC(q, certo, errados, e):
    return {"k": "mc", "q": q, "o": [certo, *errados], "e": e}
def FILL(q, code, certo, errados, e):
    return {"k": "fill", "q": q, "c": code, "b": [certo, *errados], "a": [certo], "e": e}
def ORDER(q, linhas, e):
    return {"k": "order", "q": q, "l": linhas, "e": e}
def CODE(q, starter, solucao, tests, e):
    return {"k": "code", "q": q, "starter": starter, "_sol": solucao, "tests": tests, "e": e}

def C(titulo, resumo, explica, exemplo, itens):
    return dict(combo=True, titulo=titulo, resumo=resumo, explica=explica, exemplo=exemplo, itens=itens, entrada="", cuidado=None)

EXTRAS = []
def U(titulo, desc, *lessons):
    EXTRAS.append((titulo, desc, list(lessons)))

